'use strict';
const $=id=>document.getElementById(id);
const state={token:window.__workspaceToken||'',busy:false,lookup:null,selected:null,credits:null};delete window.__workspaceToken;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let toastTimer;
function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4500)}
async function api(path,body){if(!state.token){location.replace('/');throw new Error('Enter your password to open the app.')}const response=await fetch(path,{method:body?'POST':'GET',headers:{Authorization:`Bearer ${state.token}`,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(65000)});let result;try{result=await response.json()}catch{throw new Error('The server returned an unreadable response.')}if(!response.ok)throw new Error(result.error||'The request could not be completed.');return result}
function validLinkedIn(value){try{const u=new URL(value);if(u.protocol!=='https:'||!['linkedin.com','www.linkedin.com'].includes(u.hostname)||!/^\/in\/[^/]+\/?$/i.test(u.pathname))throw Error();u.hostname='www.linkedin.com';u.search='';u.hash='';if(!u.pathname.endsWith('/'))u.pathname+='/';return u.href}catch{return null}}
function initials(name){return String(name||'?').split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'?'}
function locationText(c){return[c.city,c.state,c.country].filter(Boolean).join(', ')}
function updateCredits(summary){
  if(!summary){$('credits').hidden=true;return}
  state.credits=summary;$('credits').hidden=false;
  const total=summary.totalCreditsRemaining;
  $('credits-label').textContent=total==null?'Credits unavailable':`${Number(total).toLocaleString()} credits`;
  renderCreditsDialog();
}
function timeLabel(iso){if(!iso)return'—';const d=new Date(iso);if(Number.isNaN(+d))return'—';return d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}
function renderCreditsDialog(){
  const summary=state.credits||{};const routes=Array.isArray(summary.routes)?summary.routes:[];
  const rows=routes.map(r=>`<div class="credit-route"><div><strong>${esc((r.id||'route').toUpperCase())}</strong><small>${esc(r.keySource||'Seamless API key')}</small></div><div><strong>${r.creditsRemaining==null?'—':Number(r.creditsRemaining).toLocaleString()}</strong><small>credits</small></div><div><strong>${r.egressIp?esc(r.egressIp):(r.proxyConfigured?'Checking…':'Render shared')}</strong><small>egress IP</small></div><span class="route-state ${r.status==='READY'?'ok':'bad'}">${esc(r.status||'UNKNOWN')}</span></div>`).join('');
  $('credits-content').innerHTML=`<div class="credit-number"><strong>${summary.totalCreditsRemaining==null?'Not reported':Number(summary.totalCreditsRemaining).toLocaleString()}</strong><span>total research credits across ${Number(summary.organizationCount||routes.length||1)} configured organization${Number(summary.organizationCount||routes.length||1)===1?'':'s'}</span></div><div class="credit-route-list">${rows||'<p class="fineprint">No route details were returned.</p>'}</div><div class="credit-facts"><div><span>Balance source</span><strong>X-PublicAPI-Credits</strong></div><div><span>Unique egress required</span><strong>${summary.uniqueEgressRequired?'Yes':'No'}</strong></div><div><span>Unique egress verified</span><strong>${summary.uniqueEgressVerified?'Yes':'No'}</strong></div></div><p class="fineprint">Each balance is read directly from that organization’s Seamless API response. The total is the sum of the independently configured organization balances. Egress IPs are checked through each route, without exposing API keys or proxy credentials.</p>`;
}
function candidateCard(c,index){const loc=locationText(c);return `<article class="candidate-card ${c.exactLinkedInMatch?'exact':''}" style="--delay:${index*45}ms"><div class="candidate-main"><div class="avatar">${esc(initials(c.name))}</div><div class="candidate-identity"><div class="candidate-name-row"><h3>${esc(c.name||'Unknown contact')}</h3>${c.exactLinkedInMatch?'<span class="match-badge">Exact LinkedIn match</span>':'<span class="candidate-badge">Candidate</span>'}</div><p class="role">${esc(c.title||'Title not listed')}</p><div class="company-line"><span class="company-icon">▦</span><strong>${esc(c.company||'Company not listed')}</strong>${c.domain?`<span>· ${esc(c.domain)}</span>`:''}</div></div><button class="enrich-action" data-enrich-index="${index}">Enrich <span>→</span></button></div><div class="candidate-details">${loc?`<span>⌖ ${esc(loc)}</span>`:''}${c.department?`<span>${esc(c.department)}</span>`:''}${c.seniority?`<span>${esc(c.seniority)}</span>`:''}${c.timeAtCompany?`<span>${esc(c.timeAtCompany)} at company</span>`:''}${c.liUrl?`<a href="${esc(c.liUrl)}" target="_blank" rel="noreferrer">Open LinkedIn ↗</a>`:''}</div></article>`}
function renderLookup(result){state.lookup=result;$('results-shell').hidden=false;$('how-it-works').hidden=true;const out=$('results');
  if(result.cached&&result.job?.status==='done'){renderCompleted(result.job,true);return}
  if(result.candidates?.length){const exact=result.candidates.some(c=>c.exactLinkedInMatch);out.innerHTML=`<div class="results-heading"><div><div class="section-kicker">FREE SEARCH RESULTS</div><h2>${exact?'We found the profile.':'Choose the right person.'}</h2><p>${result.candidates.length} candidate${result.candidates.length===1?'':'s'} found for <strong>${esc(result.inferredName||'this profile')}</strong>. Review the company and role before enrichment.</p></div><div class="free-pill">✓ 0 research credits used</div></div><div class="candidate-list">${result.candidates.map(candidateCard).join('')}</div><div class="results-footnote">Search results come from Seamless contact search. No research job has been started yet.</div>`;return}
  out.innerHTML=`<div class="empty-state"><div class="empty-icon">⌕</div><div class="section-kicker">NO FREE MATCH FOUND</div><h2>We couldn’t confidently identify this profile from free search.</h2><p>${result.inferredName?`We searched for <strong>${esc(result.inferredName)}</strong>, but Seamless returned no candidates.`:'This LinkedIn slug does not contain a reliable full name to search.'} You can still enrich the exact LinkedIn URL directly, but that skips the free identity preview.</p><button class="direct-button" id="direct-enrich">Enrich exact LinkedIn URL →</button><small>This action can consume a research credit.</small></div>`}
function selectedFromJob(job){return job.selectedCandidate||{name:job.data?.fullName,company:job.data?.company,title:job.data?.title,liUrl:job.normalizedUrl}}
function renderProcessing(job){const c=selectedFromJob(job);$('results').innerHTML=`<div class="research-card"><div class="research-person"><div class="avatar large">${esc(initials(c.name))}</div><div><div class="section-kicker">RESEARCH IN PROGRESS</div><h2>${esc(c.name||'Selected contact')}</h2><p>${esc(c.title||'')}${c.title&&c.company?' · ':''}${esc(c.company||'')}</p></div><span class="research-status"><i></i> Researching</span></div><div class="progress-track"><div class="progress-line"><span></span></div><div class="progress-steps"><div class="done"><b>✓</b><span>Request accepted</span></div><div class="active"><b>2</b><span>Verifying contact data</span></div><div><b>3</b><span>Save to Supabase</span></div></div></div><div class="poll-note"><span>↻</span><div><strong>Checking Seamless every 2.5 seconds</strong><small>Polling only reads the research status and does not consume research credits.</small></div></div></div>`}
function copyButton(value,label){return value?`<button class="copy-button" data-copy="${esc(value)}">Copy</button>`:''}
function detailRow(icon,label,value,link=false){if(!value)return'';return `<div class="detail-row"><div class="detail-icon">${icon}</div><div><span>${esc(label)}</span>${link?`<a href="${esc(value)}" target="_blank" rel="noreferrer">${esc(value)}</a>`:`<strong>${esc(value)}</strong>`}</div>${copyButton(value,label)}</div>`}
function renderCompleted(job,cached=false){const d=job.data||{};$('results-shell').hidden=false;$('how-it-works').hidden=true;$('results').innerHTML=`<div class="success-banner"><span>✓</span><div><strong>${cached?'Loaded from Supabase':'Enrichment complete'}</strong><p>${cached?'No new Seamless research request was submitted.':'Contact data was saved and will be reused on future lookups.'}</p></div><div class="success-badge">${cached?'0 new credits':'Saved'}</div></div><article class="contact-result"><div class="contact-header"><div class="avatar xl">${esc(initials(d.fullName))}</div><div class="contact-heading"><div class="section-kicker">ENRICHED CONTACT</div><h2>${esc(d.fullName||'Contact')}</h2><p>${esc(d.title||'')}${d.title&&d.company?' · ':''}${esc(d.company||'')}</p></div>${d.linkedinUrl?`<a class="linkedin-open" href="${esc(d.linkedinUrl)}" target="_blank" rel="noreferrer">in <span>Open profile ↗</span></a>`:''}</div><div class="detail-grid">${detailRow('@','Email',d.email)}${detailRow('☎','Phone',d.phone)}${detailRow('◫','Company',d.company)}${detailRow('↗','Title',d.title)}${detailRow('⌘','Department',d.department)}${detailRow('◇','Seniority',d.seniority)}${detailRow('⌁','Company domain',d.companyDomain)}${detailRow('in','LinkedIn',d.linkedinUrl,true)}</div></article>`}
function renderFailure(job){const c=selectedFromJob(job);$('results').innerHTML=`<div class="error-card"><div class="error-icon">!</div><div><div class="section-kicker">RESEARCH NEEDS ATTENTION</div><h2>${esc(c.name||'Contact research')}</h2><p>${esc(job.message||`Research ended with status: ${job.status}.`)}</p></div></div>`}
function openConfirm(candidate,direct=false){state.selected={candidate,direct};$('confirm-name').textContent=direct?'Enrich this LinkedIn profile?':candidate.name||'Enrich this contact?';$('confirm-meta').textContent=direct?'No free candidate match was available, so this will research the exact LinkedIn URL.':[candidate.title,candidate.company].filter(Boolean).join(' · ');$('confirm-dialog').showModal()}
function closeConfirm(){$('confirm-dialog').close();state.selected=null}
async function runResearch(selection){const direct=selection.direct;const c=selection.candidate||{};const payload={linkedinUrl:direct?state.lookup.linkedinUrl:(c.liUrl||state.lookup.linkedinUrl),searchResultId:direct?'':c.searchResultId,routeId:direct?'':c.routeId,candidate:direct?undefined:c};$('confirm-dialog').close();state.selected=null;renderProcessing({status:'submitting',selectedCandidate:c,normalizedUrl:payload.linkedinUrl});try{let job=await api('/v1/person/research',payload);renderProcessing(job);checkConnection().catch(()=>{});for(let i=0;i<30&&['submitting','processing'].includes(job.status);i++){await new Promise(r=>setTimeout(r,2500));job=await api('/v1/person/research/status',payload.searchResultId?{searchResultId:payload.searchResultId}:{linkedinUrl:payload.linkedinUrl});if(['submitting','processing'].includes(job.status))renderProcessing(job)}if(job.status==='done'){renderCompleted(job,false);checkConnection().catch(()=>{});toast('Contact enriched and saved.')}else if(['submitting','processing'].includes(job.status)){renderProcessing(job);toast('Still processing. You can leave this page open.')}else renderFailure(job)}catch(err){toast(err.message);$('results').insertAdjacentHTML('beforeend',`<div class="inline-error">${esc(err.message)}</div>`)}}
$('chat-form').addEventListener('submit',async e=>{e.preventDefault();if(state.busy)return;const url=validLinkedIn($('linkedin').value.trim());if(!url)return toast('Paste a LinkedIn person URL such as https://www.linkedin.com/in/name/.');state.busy=true;$('send').disabled=true;$('send').innerHTML='<span>Searching…</span><span class="spinner"></span>';$('results-shell').hidden=false;$('how-it-works').hidden=true;$('results').innerHTML='<div class="searching-state"><div class="searching-orb"><span></span></div><div><strong>Finding the right person…</strong><p>Checking saved data, then running free Seamless contact search.</p></div></div>';try{const result=await api('/v1/person/lookup',{linkedinUrl:url});renderLookup(result)}catch(err){$('results').innerHTML=`<div class="inline-error large">${esc(err.message)}</div>`}finally{state.busy=false;$('send').disabled=false;$('send').innerHTML='<span>Find contact</span><span>→</span>'}});
$('results').addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.enrichIndex!==undefined){const c=state.lookup?.candidates?.[Number(b.dataset.enrichIndex)];if(c)openConfirm(c,false)}if(b.id==='direct-enrich')openConfirm(null,true);if(b.dataset.copy!==undefined){try{await navigator.clipboard.writeText(b.dataset.copy);toast('Copied to clipboard')}catch{toast('Copy is unavailable in this browser.')}}});
$('confirm-submit').onclick=()=>{if(state.selected)runResearch(state.selected)};$('confirm-cancel').onclick=closeConfirm;$('confirm-close').onclick=closeConfirm;$('credits').onclick=()=>$('credits-dialog').showModal();$('credits-close').onclick=()=>$('credits-dialog').close();
function view(prospecting){$('enriching-view').hidden=prospecting;$('prospecting-view').hidden=!prospecting;$('enriching-nav').classList.toggle('active',!prospecting);$('prospecting-nav').classList.toggle('active',prospecting);$('page-label').textContent=prospecting?'Prospecting':'Enrichment Studio'}$('enriching-nav').onclick=()=>view(false);$('prospecting-nav').onclick=()=>view(true);$('back').onclick=()=>view(false);$('logout').onclick=()=>location.replace('/');
async function checkConnection(){try{const result=await api('/status');const ok=result.database?.status==='READY'&&result.seamless?.status==='READY';$('connection-label').textContent=ok?'Connected':'Needs attention';$('connect').classList.toggle('bad',!ok);if(result.credits)updateCredits(result.credits)}catch{$('connection-label').textContent='Offline';$('connect').classList.add('bad')}}$('connect').onclick=checkConnection;
(async()=>{try{const r=await fetch('/health',{cache:'no-store'});const h=await r.json();$('build-label').textContent=`v${h.version}`;}catch{$('build-label').textContent='v33'}await checkConnection()})();
